import subprocess

# Cortex-A53 errata thunks: __CortexA53843419_XXXXX where XXXXX is the original address
# Let's find what errata thunks cover our addresses
result = subprocess.run(['nm', '-n', 'libmonosgen-2.0.so.dbg'], capture_output=True, text=True)
symbols = []
for line in result.stdout.splitlines():
    parts = line.split(' ', 2)
    if len(parts) == 3:
        symbols.append((int(parts[0], 16), parts[1], parts[2]))

# Find which thunk/function contains 0x2f4b20 and 0x2f4c84
for target in [0x2f4b20, 0x2f4c84]:
    best = None
    for addr, typ, name in symbols:
        if addr <= target and typ in ('T', 't', 'W', 'w'):
            best = (addr, name)
        elif addr > target:
            break
    print(f'0x{target:x}: contained in {best[1]} at 0x{best[0]:x} (offset +0x{target-best[0]:x})')

# Now let's find all CortexA53 thunks and try to map back
print()
print('Looking for errata thunks near our addresses...')
for addr, typ, name in symbols:
    if 'CortexA53' in name and abs(addr - 0x2f4b20) < 0x200:
        print(f'  0x{addr:x} {name}')
        # Extract original address from thunk name
        orig = name.split('_')[-1]
        orig_addr = int(orig, 16)
        print(f'    -> original address: 0x{orig_addr:x}')
        # Find function at original address
        for a2, t2, n2 in symbols:
            if a2 <= orig_addr and t2 in ('T', 't'):
                fn = (a2, n2)
            elif a2 > orig_addr:
                break
        print(f'    -> function: {fn[1]} at 0x{fn[0]:x}')
"

