    parts = line.split(None, 2)
    if len(parts) == 3:
        try:
            symbols.append((int(parts[0], 16), parts[1], parts[2]))
        except ValueError:
            pass

# Find containing symbol for each address
for target in [0x2f4b20, 0x2f4c84, 0x2c1a40]:
    best = None
    next_sym = None
    for i, (addr, typ, name) in enumerate(symbols):
        if addr <= target:
            best = (addr, typ, name)
        if addr > target and next_sym is None:
            next_sym = (addr, typ, name)
    offset = target - best[0] if best else 0
    print(f'0x{target:x}: {best[2]} (0x{best[0]:x}, type={best[1]}, +0x{offset:x})')
    if next_sym:
        print(f'  next: {next_sym[2]} at 0x{next_sym[0]:x}')
